filesystem::path default_cache\(\) \{
  const char\* xdg = std::getenv\("XDG_CACHE_HOME"\);
  if \(xdg && \*xdg\) return filesystem::path\(xdg\) / "sicx";
  const char\* home = std::getenv\("HOME"\);
  if \(home && \*home\) return filesystem::path\(home\) / "\.cache/sicx";
  fail\(sic::ErrorKind::invalid_argument, "remote: no user cache directory; pass --cache DIR"\);
\}

T\ parse_number\(std::string_view\ text,\ std::string_view\ name,\ ErrorKind\ kind,\
\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ T\ low\ =\ std::numeric_limits<T>::lowest\(\),\ T\ high\ =\ std::numeric_limits<T>::max\(\),\
\ \ \ \ \ \ \ \ \ \ \ \ \ \ \ int\ base\ =\ [0-9]+(?:\.[0-9]+)?\)\ \{

int default_producer_workers\(unsigned exponent\) \{
  // Small analytic grids do not amortize a large worker team's dispatch and
  // allocator costs\. Saturate at the physical cores, without counting SMT\.
  const int work_limit = exponent < 9 \? std::min\(32, 1 << \(exponent > 2 \? exponent - 2 : 0\)\) : 64;
  return std::min\(static_cast<int>\(sic::support::resources::requested_threads\(nullptr\)\),
                  work_limit\);
\}

